/**
 * Embed skills/geoly-mcp/ into the binary as an offline fallback for `geoly init`.
 *
 *   node scripts/gen-skill-bundle.mjs           → writes src/skill-bundle.generated.ts
 *   node scripts/gen-skill-bundle.mjs --check   → exits 1 if the generated file is stale
 *
 * The live copy always wins at install time (app.geoly.ai/skills/geoly-mcp.zip); this bundle
 * only matters offline. release.mjs runs --check so a release can never ship a stale bundle.
 */
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(root, 'skills', 'geoly-mcp');
const OUT = join(root, 'src', 'skill-bundle.generated.ts');

function collect(dir, base = dir) {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name);
    if (name === 'SYNC.md') continue; // repo-only notice, not part of the published skill
    if (statSync(full).isDirectory()) out.push(...collect(full, base));
    else out.push({ path: `geoly-mcp/${relative(base, full).split(/[\\/]/).join('/')}`, data: readFileSync(full) });
  }
  return out;
}

const files = collect(SRC);
const skill = files.find((f) => f.path === 'geoly-mcp/SKILL.md');
const version = /^\s*version:\s*"([^"]+)"/m.exec(skill?.data.toString('utf8') ?? '')?.[1];
if (!version) throw new Error('skills/geoly-mcp/SKILL.md has no metadata.version');

const body =
  `// GENERATED by scripts/gen-skill-bundle.mjs from skills/geoly-mcp/ — do not edit.\n` +
  `// Offline fallback for \`geoly init\`; the live bundle on app.geoly.ai wins when reachable.\n` +
  `export const SKILL_BUNDLE_VERSION = ${JSON.stringify(version)};\n` +
  `export const SKILL_BUNDLE_FILES: ReadonlyArray<{ path: string; sha256: string; base64: string }> = [\n` +
  files
    .map(
      (f) =>
        `  { path: ${JSON.stringify(f.path)}, sha256: ${JSON.stringify(createHash('sha256').update(f.data).digest('hex'))}, base64: ${JSON.stringify(f.data.toString('base64'))} },`,
    )
    .join('\n') +
  `\n];\n`;

if (process.argv.includes('--check')) {
  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (current !== body) {
    console.error('skill bundle is stale: run `node scripts/gen-skill-bundle.mjs` and commit src/skill-bundle.generated.ts');
    process.exit(1);
  }
  console.log(`skill bundle up to date (${version}, ${files.length} files)`);
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${relative(root, OUT)} (${version}, ${files.length} files)`);
}
